var a=[{title:`De ce să le combini`,text:`Antrenamentul de forță îmbunătățește forța și funcția musculară, iar activitatea aerobă susține rezistența și sănătatea inimii și a plămânilor. Ghidurile de sănătate publică le recomandă pe amândouă. Dacă faci doar una, unele părți ale condiției tale pot rămâne în urmă, mai ales când obiectivele tale de zi cu zi includ forța, capacitatea de a merge și menținerea activă pe perioade lungi.`},{title:`Efectul de interferență`,text:`Cantități foarte mari de muncă de rezistență pot reduce uneori câștigurile în putere explozivă sau unele rezultate de forță, față de antrenamentul de forță singur. Analizele recente găsesc însă că antrenamentul combinat îmbunătățește în general capacitatea aerobă și forța împreună, iar majoritatea celor care se antrenează recreativ nu pierd nimic real din creșterea musculară din cauza lui.`},{title:`Alege o ordine practică`,text:`Dacă forța este prioritatea ta, fă ridicările solicitante cât ești proaspăt și cardio ușor după aceea. Dacă condiția fizică este obiectivul tău principal, fă mai întâi munca importantă de rezistență. Distanțarea sesiunilor grele la câteva ore sau în zile diferite poate ajuta la oboseală, mai ales în antrenamentul avansat.`},{title:`Echilibrează zilele grele și ușoare`,text:`De exemplu, fă două zile de forță pentru tot corpul plus două sau trei plimbări alerte și o sesiune opțională de ciclism moderat. Un sportiv mai experimentat poate avea nevoie să programeze cu grijă alergările grele și sesiunile de forță pentru picioare. Dacă performanța și refacerea au de suferit, nu mai adăuga intervale cu efort maxim peste fiecare antrenament de picioare.`},{title:`Folosirea TrainUp`,text:`Obiectivul tău din Profil (condiție fizică generală, forță sau condiție fizică) îți arată ce fel de muncă să pui pe primul loc, în timp ce te antrenezi în continuare pentru ambele. Cardio nu strică automat progresul la forță. Urmărește repetările ratate și efortul tău mediu în Istoric. Când îți regenerezi planul, acesta devine mai ușor dacă 2 din ultimele tale 3 antrenamente au fost foarte grele (RPE 9 sau mai mult) sau finalizate sub 60%.`}];var t=[{label:`Analiză de sinteză 2026: antrenamentul concurent de forță și rezistență`,url:`https://pubmed.ncbi.nlm.nih.gov/41762427/`},{label:`CDC: recomandări de activitate fizică pentru adulți`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};